mapper.select:
SELECT /* kh.com.copilot.app.csm.dao.LoginDao.selectListUserMgt */ USR.OPER_GROUP_CD AS "operGroupCd" , USR.UNO AS "uno" , USR.USER_NAME AS "userName" --, USR.EMPLOYEE_ID AS "empId" , USR.PWD AS "pwd" , USR.BRN_CODE AS "brnCode" , USR.POS_CODE AS "postCode" , USR.DEP_CODE AS "regiCode" , USR.REG_CODE AS "postCode" , USR.USE_YN AS "useYn" , TO_CHAR(USR.SYS_CREATE_YMS, 'DDMMYYYY') AS "sysCreateYms" , TO_CHAR(USR.SYS_UPDATED_YMS, 'DDMMYYYY') AS "sysLastYms" , USR.SYS_CREATE_UNO AS "sysCreateUno" , USR.SYS_UPDATED_UNO AS "sysLastUno" , COUNT(*) OVER () AS "totalCnt" FROM ${schema}.TSCSM0002 USR WHERE 1=1 AND USR.OPER_GROUP_CD = #{operGroupCd}
AND UPPER(USR.UNO) = UPPER(#{uno})
AND USR.BRN_CODE = #{brnCode}
OFFSET (#{pageCnt}*(#{pageNo}-1)) ROWS FETCH FIRST #{pageCnt} ROWS ONLY
